const std=@import("std");const M=@import("experimental/hydration_lifecycle_core.zig");const T=@import("experimental/hydration_manual_transfer.zig");
const Planet=struct{worldMode:M.Mode=.origin,microbeCells:[2]M.Cell=.{M.initialized(1),M.initialized(2)},microbeStats:M.Stats=.{.next_lineage=10},pub fn getNeighbours(_: *@This(),from:usize)[1]usize{return .{1-from};}};
const State=struct{planet:Planet=.{},paused:bool=true,gameTime:f64=100};
fn setup()State{var s:State=.{};s.planet.microbeCells[0].cohorts[0]=.{.biomass=0.2,.support_mass=0.05,.retention_allocation=0.25,.stored_water=0.1,.lineage=1};s.planet.microbeCells[0].liquid_return=0.012;s.planet.microbeCells[0].vapor_return=0.013;s.planet.microbeCells[1].liquid_return=0.014;s.planet.microbeCells[1].vapor_return=0.015;return s;}
test "import-only production transport carries owned water but no patch escrows"{var s=setup();const before=s;const ticket=T.prepare(&s,7,0,0,1).?;const receipt=T.execute(&s,7,ticket);try std.testing.expect(receipt.ok);var expected=before;expected.planet.microbeCells[1].cohorts[0]=before.planet.microbeCells[0].cohorts[0];expected.planet.microbeCells[0].cohorts[0]=.{};try std.testing.expectEqualDeep(expected,s);const moved=s;try std.testing.expect(!T.execute(&s,7,ticket).ok);try std.testing.expectEqualDeep(moved,s);}
test "hydration and escrow stale changes reject atomically"{for(0..4)|change|{var s=setup();const ticket=T.prepare(&s,7,0,0,1).?;switch(change){0=>s.planet.microbeCells[0].cohorts[0].stored_water=0.09,1=>s.planet.microbeCells[0].cohorts[0].retention_allocation=0.3,2=>s.planet.microbeCells[0].liquid_return+=0.01,else=>s.planet.microbeCells[1].vapor_return+=0.01}const before=s;try std.testing.expect(!T.execute(&s,7,ticket).ok);try std.testing.expectEqualDeep(before,s);}}
test "invalid hydration and full target cannot destroy water"{for(0..4)|change|{var s=setup();switch(change){0=>s.planet.microbeCells[0].cohorts[0].stored_water=1,1=>s.planet.microbeCells[0].cohorts[0].stored_water=std.math.nan(f64),2=>s.planet.microbeCells[1].liquid_return=-1,else=>{for(&s.planet.microbeCells[1].cohorts,0..)|*c,i|c.*=.{.biomass=0.01,.lineage=i+2};}}const before=try std.json.stringifyAlloc(std.testing.allocator,s,.{});defer std.testing.allocator.free(before);if(T.prepare(&s,7,0,0,1))|ticket|{try std.testing.expect(!T.execute(&s,7,ticket).ok);}const after=try std.json.stringifyAlloc(std.testing.allocator,s,.{});defer std.testing.allocator.free(after);try std.testing.expectEqualStrings(before,after);}}
